import{_ as r,o,c as a,ag as t}from"./chunks/framework.cyF4XceO.js";const f=JSON.parse('{"title":"HCL から公開済み Form を管理する","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docs/getting-started.md","filePath":"ja/docs/getting-started.md"}'),s={name:"ja/docs/getting-started.md"};function i(d,e,n,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[t(`<p>日本語: <a href="/docs/getting-started.html">English</a></p><h1 id="hcl-から公開済み-form-を管理する" tabindex="-1">HCL から公開済み Form を管理する <a class="header-anchor" href="#hcl-から公開済み-form-を管理する" aria-label="Permalink to &quot;HCL から公開済み Form を管理する&quot;">​</a></h1><p>この手順は、Registry で公開済みの Provider 4.1.0 と Host API v1 contract を使います。 現在のsource targetである Provider 5.0.0 は、release ledger 上では candidate-only です。 Provider 5 には別の Host API v2 設定と fresh-install state model があり、Provider 4 の state は自動移行されません。Provider 5 を評価する場合は<a href="/docs/provider-host-api-v2-source.html">consumer reference</a> を参照してください。</p><p>このガイドでは、Random Provider と Takoform のリソースを 1 つずつ含む Terraform / OpenTofu module を紹介します。使用する設定は <a href="/examples/getting-started/main.tf"><code>examples/getting-started/main.tf</code></a> です。</p><p>この Provider は、公開済みの Takoform Form を HCL から管理するためのものです。 AWS、Cloudflare などの Provider と同じ立場にあり、各 source address を <code>required_providers</code> に宣言すると、Terraform / OpenTofu が依存関係を管理します。 この Provider が Host を作成したり、実行先を選んだり、すべての Form の一覧を 提供したりするわけではありません。</p><h2 id="始める前に" tabindex="-1">始める前に <a class="header-anchor" href="#始める前に" aria-label="Permalink to &quot;始める前に&quot;">​</a></h2><p>plan を作る前に、次を用意してください。</p><ul><li>Terraform または OpenTofu と、互換性のある Takoform Host。</li><li>Host 運用者から受け取った接続先、正確な Space ID、および Host が必要とする 場合は bearer token。Host は resource が使う正確な FormRef に対応している必要が あります。</li><li>Random Provider にクラウド認証情報は不要です。Takoform のリソースを apply すると、 選択した Host は変更されます。</li></ul><p>Takoform の接続先と Space は選択した Host が指定します。既定の Host や Space はありません。bearer token を HCL や変数ファイルに書かないでください。必要なら 普段の方法で秘密情報を <code>TAKOFORM_TOKEN</code> として実行環境へ渡します。Provider は <code>TAKOFORM_ENDPOINT</code> と <code>TAKOFORM_SPACE</code> も環境変数から読み取れます。</p><h2 id="_2-つの-provider-を宣言する" tabindex="-1">2 つの Provider を宣言する <a class="header-anchor" href="#_2-つの-provider-を宣言する" aria-label="Permalink to &quot;2 つの Provider を宣言する&quot;">​</a></h2><p>同梱の<a href="/examples/getting-started/main.tf">サンプル module</a>を使います。 <code>registry.terraform.io/tako0614/takoform</code> と <code>registry.terraform.io/hashicorp/random</code> を宣言しています。Random のリソースが生成する 値を通常の HCL reference で <code>takoform_edge_kv_namespace</code> の名前に使います。Random Provider にクラウドアカウントの設定は不要です。Takoform Provider が選択した Host の namespace を管理します。クラウド Provider との連携例は既存の <a href="/examples/native-provider-composition/main.tf">AWS S3 サンプル</a>を参照してください。</p><p>サンプルのディレクトリで HCL の整形、初期化、検証を行います。入力と認証情報を 用意したら、apply の前に plan を確認してください。</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd examples/getting-started</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu fmt -check</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu init</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu validate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu plan</span></span></code></pre></div><p>Terraform を使う場合は <code>tofu</code> の代わりに <code>terraform</code> を実行します。Host の接続先と Space ID の 2 つを、普段使っている方法で module に渡してください。apply すると選択した Host に namespace が作られるため、対象と変更内容を確認してから実行してください。</p><p>この resource は公開済みの <a href="https://edge.forms.takoform.com/forms/EdgeKVNamespace/0.1.0/" target="_blank" rel="noreferrer">EdgeKVNamespace Form、definition 0.1.0</a> に対応します。apply 前に、互換 Host がその正確な FormRef に対応していることを確認 してください。provider-neutral な Host contract は別の <a href="https://takoform.com/host-api/" target="_blank" rel="noreferrer">Host API ドキュメント</a>にあります。そこに書かれた contract は、Host endpoint や credentials を提供するものではありません。</p><h2 id="provider-の版と-form-identity" tabindex="-1">Provider の版と Form identity <a class="header-anchor" href="#provider-の版と-form-identity" aria-label="Permalink to &quot;Provider の版と Form identity&quot;">​</a></h2><p>サンプルの <code>version = &quot;~&gt; 4.0&quot;</code> は Provider package の 4.x 系を選びます。このガイドで 扱う公開済み release は Provider 4.1.0 です。版を固定する場合は <code>version = &quot;= 4.1.0&quot;</code> とします。 <code>tofu init</code> は選択した Provider package と checksum を <code>.terraform.lock.hcl</code> に記録 します。実際の module ではこの lock file を commit してください。この制約は<strong>Form の版を固定しません</strong>。各 Provider release が resource type と正確な FormRef を対応 付け、resource state はその API version、kind、definition version、schema digest を 記録します。このサンプルの対応先は <code>edge.forms.takoform.com/EdgeKVNamespace</code> の definition <code>0.1.0</code> です。完全な identity と state の挙動は<a href="/docs/resources/edge_kv_namespace.html#exact-formref">resource reference</a> を参照してください。</p><h2 id="workerversion-の機密入力" tabindex="-1">WorkerVersion の機密入力 <a class="header-anchor" href="#workerversion-の機密入力" aria-label="Permalink to &quot;WorkerVersion の機密入力&quot;">​</a></h2><p><code>TAKOFORM_TOKEN</code> は Host API 用の credentials です。Worker code が実行時に必要とする アプリケーションの秘密情報とは別です。 <a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code></a> では <code>required_sensitive_vars</code> に必要な値の名前だけを宣言します。値は実行 runner が対応 する ephemeral root-variable 経路から、Apply 時だけ Provider の <code>runtime_inputs</code> map へ渡します。値は保存済み plan や Terraform / OpenTofu state に入りません。HCL の literal、<code>vars_json</code>、通常の <code>.tfvars</code>、command argument、または環境変数へ値を書かない でください。この経路を設定する前に <a href="/docs/resources/worker_version.html#run-scoped-sensitive-inputs">Apply 単位の機密入力</a>を 読んでください。nonce、Provider instance、Apply 時の map を一致させる必要があり、 ephemeral 配送に対応しない runner ではこれらの入力を適用できません。</p><h2 id="次に読むもの" tabindex="-1">次に読むもの <a class="header-anchor" href="#次に読むもの" aria-label="Permalink to &quot;次に読むもの&quot;">​</a></h2><ul><li><a href="/docs/reference.html#resource-reference">全 resource の reference</a> と <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/forms/README.md" target="_blank" rel="noreferrer">Provider から Form への対応一覧</a></li><li>provider-neutral な契約が必要な場合は、別文書の<a href="https://takoform.com/host-api/" target="_blank" rel="noreferrer">Takoform Host API</a></li><li>Provider 3 から更新する前に<a href="./../../release/migrations/v3-to-v4.html">Provider 3 から 4 への移行ガイド</a></li></ul>`,21)])])}const h=r(s,[["render",i]]);export{f as __pageData,h as default};
